#!/bin/bash
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard
B64_skykin_config_php=''
echo "${B64_skykin_config_php}" | base64 -d > /tmp/skykin_config.php
docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
B64_supervisor_php=''
echo "${B64_supervisor_php}" | base64 -d > /tmp/supervisor.php
docker cp /tmp/supervisor.php skykin-web:$WEB/supervisor.php
B64_index_php=''
echo "${B64_index_php}" | base64 -d > /tmp/index.php
docker cp /tmp/index.php skykin-web:$WEB/index.php
B64_data_php=''
echo "${B64_data_php}" | base64 -d > /tmp/data.php
docker cp /tmp/data.php skykin-web:$WEB/data.php
docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$ivr=["direction"=>"inbound","billsec"=>40,"waitsec"=>0,"last_arg"=>"","cc_agent_bridged"=>"","bridge_uuid"=>""];
$in=["direction"=>"inbound","billsec"=>90,"waitsec"=>0,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"","bridge_uuid"=>""];
$out=["direction"=>"outbound","billsec"=>30,"waitsec"=>0,"last_arg"=>"","cc_agent_bridged"=>"","bridge_uuid"=>""];
echo skykin_cdr_result_label($ivr)," ",skykin_cdr_result_label($in)," ",skykin_cdr_result_label($out),"\n";
'
echo DONE
